using System.Linq; using System.Web; using System.Web.Mvc;
namespace OrderFlow.MVC.Filters { public class AuthorizeRoleAttribute : AuthorizeAttribute { private readonly string[] _roles; public AuthorizeRoleAttribute(params string[] roles) { _roles = roles; } protected override bool AuthorizeCore(HttpContextBase context) { return context.User?.Identity?.IsAuthenticated == true && _roles.Any(context.User.IsInRole); } protected override void HandleUnauthorizedRequest(AuthorizationContext context) { context.Result = new HttpStatusCodeResult(403, "Your role is not authorized for this operation."); } } }
